import{_ as r,o as a,c as e,ag as d}from"./chunks/framework.Aev9KvMf.js";const q=JSON.parse('{"title":"技能提升补贴 · 考出证能领的政府钱","description":"失业保险技能提升补贴官方申领教程：目录内证书按等级最高 2000 元级补贴，线上申领入口与条件，防\\"机构代领\\"骗局。","frontmatter":{"title":"技能提升补贴 · 考出证能领的政府钱","issuer":"人力资源社会保障部","source_tier":"一级来源","version":"—","published":"—","source_url":"https://si.12333.gov.cn/","status":"现行服务","tags":["官方查询","技能补贴","考证","社保","家庭财务"],"type":"查询页","reviewed":false,"description":"失业保险技能提升补贴官方申领教程：目录内证书按等级最高 2000 元级补贴，线上申领入口与条件，防\\"机构代领\\"骗局。"},"headers":[],"relativePath":"query/skill-subsidy.md","filePath":"query/skill-subsidy.md"}'),o={name:"query/skill-subsidy.md"};function h(l,t,s,n,i,u){return a(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="技能提升补贴-·-考出证能领的政府钱" tabindex="-1">技能提升补贴 · 考出证能领的政府钱 <a class="header-anchor" href="#技能提升补贴-·-考出证能领的政府钱" aria-label="Permalink to &quot;技能提升补贴 · 考出证能领的政府钱&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">待核验</p><p>本页由 AI 会话信息整理（国家社保平台入口已核验可达）；补贴标准与条件<strong>各地有差异</strong>，以当地规定和 12333 答复为准。</p></div><blockquote><p><strong>官方入口</strong>：<a href="https://si.12333.gov.cn/" target="_blank" rel="noreferrer">国家社会保险公共服务平台</a>（&quot;职业技能提升补贴申领&quot;模块）、各地人社 App/经办机构；咨询 12333。· 一级来源</p></blockquote><h2 id="速览卡" tabindex="-1">速览卡 <a class="header-anchor" href="#速览卡" aria-label="Permalink to &quot;速览卡&quot;">​</a></h2><p>企业在职职工依法缴纳<strong>失业保险</strong>、考取**《国家职业资格目录》内<strong>的证书（或职业技能等级证书）的，可申领</strong>技能提升补贴**：国家基准为初级（五级）1000 元、中级（四级）1500 元、高级（三级）2000 元，<strong>各地可上浮</strong>（待核验）。这是&quot;考证防坑&quot;篇的另一半：目录内的证考下来，政府真给钱。</p><h2 id="申领条件-待核验" tabindex="-1">申领条件（待核验） <a class="header-anchor" href="#申领条件-待核验" aria-label="Permalink to &quot;申领条件（待核验）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>条件</th><th>说明</th></tr></thead><tbody><tr><td>参保身份</td><td>企业在职职工（缴纳失业保险累计 <strong>12 个月</strong>及以上；部分地区放宽，含领取失业保险金人员）</td></tr><tr><td>证书范围</td><td><a href="/SageRelay/query/cert-search.html">国家职业资格目录</a>内证书，或官方可查的职业技能等级证书</td></tr><tr><td>时限</td><td><strong>证书核发之日起 12 个月内</strong>申领（待核验）</td></tr><tr><td>次数</td><td>同一证书只能享受一次；每人每年享受补贴次数有上限（待核验）</td></tr></tbody></table><h2 id="_30-秒申领步骤-待核验" tabindex="-1">30 秒申领步骤（待核验） <a class="header-anchor" href="#_30-秒申领步骤-待核验" aria-label="Permalink to &quot;30 秒申领步骤（待核验）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>步骤</th><th>怎么做</th></tr></thead><tbody><tr><td>1</td><td>先确认证书可查：<a href="/SageRelay/query/cert-search.html">证书查询</a>能查到</td></tr><tr><td>2</td><td>登录<a href="https://si.12333.gov.cn/" target="_blank" rel="noreferrer">国家社保平台</a> → &quot;职业技能提升补贴申领&quot;，或用当地人社 App/小程序</td></tr><tr><td>3</td><td>填证书编号，系统联网核验后按当地标准发放（一般发放至社保卡金融账户或银行卡）</td></tr><tr><td>4</td><td>线上办不了的：带身份证、证书到参保地失业保险经办机构办理</td></tr></tbody></table><h2 id="结果怎么读" tabindex="-1">结果怎么读 <a class="header-anchor" href="#结果怎么读" aria-label="Permalink to &quot;结果怎么读&quot;">​</a></h2><table tabindex="0"><thead><tr><th>看到什么</th><th>说明</th></tr></thead><tbody><tr><td>审核通过、补贴到账</td><td>正常（<a href="https://si.12333.gov.cn/" target="_blank" rel="noreferrer">社保平台</a>）</td></tr><tr><td>提示&quot;不符合条件&quot;</td><td>多为缴费月数不足、证书不在目录/超时限——先按提示对照，再问 12333</td></tr><tr><td>当地无此模块</td><td>部分地区走线下经办窗口，电话 12333 确认</td></tr></tbody></table><h2 id="领前五问自检-全-是-再去申领" tabindex="-1">领前五问自检（全&quot;是&quot;再去申领） <a class="header-anchor" href="#领前五问自检-全-是-再去申领" aria-label="Permalink to &quot;领前五问自检（全&quot;是&quot;再去申领）&quot;">​</a></h2><ol><li>我在<strong>企业</strong>工作并缴纳失业保险满 12 个月了吗（事业单位/灵活就业/城乡居民参保的一般不适用，部分地区放宽——问 12333）？</li><li>证书在<a href="/SageRelay/query/cert-search.html">《国家职业资格目录》</a>内，或是官方联网可查的技能等级证书吗？</li><li>证书是<strong>核发之日起 12 个月内</strong>吗（超期不补）？</li><li>这张证书今年没领过补贴、以前也没用同一证书领过吗？</li><li>我的社保卡<strong>金融功能已激活</strong>吗（多数地区发放到社保卡金融账户，未激活会卡在最后一步）？</li></ol><h2 id="线下申领要带什么-线上办不了的备选-待核验" tabindex="-1">线下申领要带什么（线上办不了的备选，待核验） <a class="header-anchor" href="#线下申领要带什么-线上办不了的备选-待核验" aria-label="Permalink to &quot;线下申领要带什么（线上办不了的备选，待核验）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>材料</th><th>说明</th></tr></thead><tbody><tr><td>身份证 / 社保卡</td><td>金融功能已激活更稳妥</td></tr><tr><td>证书原件或编号</td><td>系统联网核验用</td></tr><tr><td>银行卡信息</td><td>部分地区发放到本人银行卡而非社保卡</td></tr><tr><td>参保证明</td><td>一般系统可直接核验，个别地区要求自带</td></tr></tbody></table><p>发放周期：审核通过后发放至本人账户，<strong>周期各地不同</strong>（多为数周内）——超出正常周期先查申领状态，再打 12333。</p><h2 id="常见驳回原因与对策" tabindex="-1">常见驳回原因与对策 <a class="header-anchor" href="#常见驳回原因与对策" aria-label="Permalink to &quot;常见驳回原因与对策&quot;">​</a></h2><table tabindex="0"><thead><tr><th>驳回提示</th><th>多半是</th><th>对策</th></tr></thead><tbody><tr><td>&quot;参保缴费不满足条件&quot;</td><td>失业保险不足 12 个月 / 中途断缴</td><td>满足月数后再申领；部分地区放宽，12333 确认口径</td></tr><tr><td>&quot;证书信息核验不通过&quot;</td><td>证书不在目录内或联网查不到</td><td>先到<a href="/SageRelay/query/cert-search.html">证书查询</a>自查——查不到的证连申领资格都没有</td></tr><tr><td>&quot;超出申领时限&quot;</td><td>核发已超 12 个月</td><td>无法补领，下次拿证注意时限</td></tr><tr><td>&quot;已享受过该证书补贴&quot;</td><td>同一证书只能领一次</td><td>换更高级别证书（如中级→高级）可再领，规则见当地文件</td></tr></tbody></table><h2 id="与-培训补贴-不是一回事" tabindex="-1">与&quot;培训补贴&quot;不是一回事 <a class="header-anchor" href="#与-培训补贴-不是一回事" aria-label="Permalink to &quot;与&quot;培训补贴&quot;不是一回事&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>技能提升补贴（本页）</th><th>职业技能培训补贴</th></tr></thead><tbody><tr><td>给谁</td><td>考出证<strong>之后</strong>申领</td><td>参加定向培训<strong>过程中/结业</strong>享受</td></tr><tr><td>条件核心</td><td>失业保险参保职工</td><td>以当地就业培训政策为准（含部分无业人群）</td></tr><tr><td>查询</td><td><a href="https://si.12333.gov.cn/" target="_blank" rel="noreferrer">国家社保平台</a></td><td>当地人社局官网 / 12333</td></tr></tbody></table><p>两笔补贴在部分地区可分别享受，但<strong>同一证书同一时期不得重复享受同类补贴</strong>（待核验）——报名培训机构前先问清&quot;这班走哪条补贴&quot;。</p><h2 id="避坑要点" tabindex="-1">避坑要点 <a class="header-anchor" href="#避坑要点" aria-label="Permalink to &quot;避坑要点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>骗局话术</th><th>官方事实</th></tr></thead><tbody><tr><td>&quot;报我们班考完，补贴打到我们卡里再给你&quot;</td><td>补贴<strong>直接发给个人</strong>，不经过任何机构——要求代收的都是坑</td></tr><tr><td>&quot;包考包补贴，等于免费拿证&quot;</td><td>补贴有条件（参保、目录内、时限），先查自己是否符合，别为补贴反向买课</td></tr><tr><td>【本站提示】没有失业保险参保记录的（灵活就业、城乡居民）一般不适用本补贴——别信&quot;人人可领&quot;</td><td>—</td></tr></tbody></table><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li>证书核验与目录：<a href="/SageRelay/query/cert-search.html">考证防坑 · 证书查询</a></li><li>政策咨询与申领：<a href="/SageRelay/query/si-12333.html">国家社保平台</a> · 12333</li></ul><h2 id="溯源" tabindex="-1">溯源 <a class="header-anchor" href="#溯源" aria-label="Permalink to &quot;溯源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>政策</td><td>失业保险技能提升补贴（人社部发〔2017〕40 号建立，后续文件延续调整，<strong>待核验</strong>）</td></tr><tr><td>入口</td><td><a href="https://si.12333.gov.cn/" target="_blank" rel="noreferrer">si.12333.gov.cn</a>（已核验可达）· 12333</td></tr></tbody></table>',27)])])}const c=r(o,[["render",h]]);export{q as __pageData,c as default};
